-- =============================================================================
-- FICHIER GÉNÉRÉ par infra/scripts/build-content-seed.mjs à partir de db/content/.
-- Ne pas modifier à la main : modifier db/content puis relancer le script.
--
-- Contenu des parcours « Administrateur Linux » et « Technicien informatique » :
-- 21 fiches commandes, 5 cours.
-- Rejouable : un contenu déjà présent (même identifiant d'URL) n'est jamais réécrit, pour ne pas
-- écraser une modification faite et relue dans le back-office.
-- =============================================================================
BEGIN;

INSERT INTO skills.skills (code, name, platform) VALUES
  ('linux.shell', 'Ligne de commande Linux', 'linux'),
  ('linux.permissions', 'Droits et propriétaires Linux', 'linux'),
  ('linux.processes', 'Processus et signaux Linux', 'linux'),
  ('linux.network', 'Diagnostic réseau sous Linux', 'linux'),
  ('linux.storage', 'Stockage et espace disque Linux', 'linux'),
  ('windows.network', 'Diagnostic réseau sous Windows', 'windows'),
  ('windows.disk', 'Disques et système de fichiers Windows', 'windows')
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------- Fiches ----
CREATE TEMP TABLE seeded_commands (slug text PRIMARY KEY, alternatives jsonb NOT NULL) ON COMMIT DROP;

CREATE FUNCTION pg_temp.seed_command(c jsonb) RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  cid uuid;
  sid uuid;
  s jsonb;
BEGIN
  IF EXISTS (SELECT 1 FROM kb.commands WHERE slug = c->>'slug') THEN RETURN; END IF;
  INSERT INTO kb.commands (slug, name, platform, shell, summary, history, internals, syntax, why, when_to_use, context,
                           best_practices, common_errors, risk_level, risks, difficulty, requires_admin, status)
  VALUES (c->>'slug', c->>'name', (c->>'platform')::platform.os_platform, c->>'shell', c->>'summary', c->>'history',
          c->>'internals', c->>'syntax', c->>'why', c->>'whenToUse', c->>'context',
          ARRAY(SELECT jsonb_array_elements_text(c->'bestPractices')), c->'commonErrors',
          (c->>'riskLevel')::platform.risk_level, c->'risks', (c->>'difficulty')::platform.difficulty,
          (c->>'requiresAdmin')::boolean, 'published')
  RETURNING id INTO cid;

  INSERT INTO kb.command_parameters (command_id, flag, description, risk_level, position)
  SELECT cid, p->>'flag', p->>'description', (p->>'riskLevel')::platform.risk_level, i - 1
    FROM jsonb_array_elements(c->'parameters') WITH ORDINALITY AS t(p, i);
  INSERT INTO kb.command_examples (command_id, title, code, explanation, is_real_case, position)
  SELECT cid, e->>'title', e->>'code', e->>'explanation', (e->>'isRealCase')::boolean, i - 1
    FROM jsonb_array_elements(c->'examples') WITH ORDINALITY AS t(e, i);
  FOR s IN SELECT * FROM jsonb_array_elements(c->'sources') LOOP
    INSERT INTO kb.sources (title, url, publisher) VALUES (s->>'title', s->>'url', s->>'publisher')
    ON CONFLICT (url) DO UPDATE SET title = EXCLUDED.title
    RETURNING id INTO sid;
    INSERT INTO kb.command_sources (command_id, source_id) VALUES (cid, sid) ON CONFLICT DO NOTHING;
  END LOOP;
  INSERT INTO seeded_commands VALUES (c->>'slug', c->'alternatives');
END
$fn$;

SELECT pg_temp.seed_command($json${"slug":"linux-ls","name":"ls","platform":"linux","shell":"bash","difficulty":"beginner","requiresAdmin":false,"summary":"Liste le contenu d’un répertoire, avec au besoin les droits, le propriétaire, la taille et la date.","history":"Présente dès la première version d’Unix (1971), sous le nom hérité de la commande « list » de Multics.","internals":"ls lit les entrées du répertoire (getdents) puis, en format long, appelle stat() sur chaque fichier pour obtenir droits, propriétaire, taille et dates.","syntax":"ls [options] [chemin…]","why":"Avant de modifier, copier ou supprimer quoi que ce soit, il faut voir ce qui est réellement là, et à qui cela appartient. La plupart des erreurs « fichier introuvable » ou « permission refusée » se comprennent en une ligne de ls -l.","whenToUse":"Avant toute manipulation de fichiers, pour vérifier un chemin, un propriétaire ou des droits. Pour chercher un fichier dans une arborescence, préférez find ; pour l’espace occupé, du.","context":"Tout shell POSIX. Aucun droit particulier : il faut seulement le droit de lecture (r) et de traversée (x) sur le répertoire listé.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule : ne modifie rien."}],"bestPractices":["Utiliser ls -la pour voir aussi les fichiers cachés (commençant par un point), souvent des fichiers de configuration.","Ajouter -h pour des tailles lisibles (Ko, Mo).","Ne pas analyser la sortie de ls dans un script : les noms avec espaces la cassent. Utiliser find ou une boucle sur les globs."],"commonErrors":[{"error":"ls: cannot open directory: Permission denied","cause":"Il manque le droit r (lister) ou x (traverser) sur le répertoire.","fix":"Vérifier les droits du répertoire parent avec ls -ld chemin, puis demander l’accès ou utiliser sudo si c’est justifié."}],"parameters":[{"flag":"-l","description":"Format long : type, droits, nombre de liens, propriétaire, groupe, taille, date.","riskLevel":"none"},{"flag":"-a","description":"Affiche aussi les fichiers cachés, dont . et ..","riskLevel":"none"},{"flag":"-h","description":"Tailles lisibles par un humain (avec -l).","riskLevel":"none"},{"flag":"-t","description":"Trie par date de modification, le plus récent d’abord.","riskLevel":"none"},{"flag":"-d","description":"Affiche le répertoire lui-même plutôt que son contenu (utile avec -l pour voir ses droits).","riskLevel":"none"}],"examples":[{"title":"Voir les fichiers récents d’un dossier de journaux","code":"ls -lht /var/log | head","explanation":"Les fichiers modifiés en dernier apparaissent en premier : c’est là que se trouve l’incident en cours.","isRealCase":true},{"title":"Comprendre un « Permission denied »","code":"ls -ld /srv/app /srv/app/config.yml","explanation":"Montre les droits du dossier et du fichier : il faut x sur le dossier pour atteindre le fichier, et r sur le fichier pour le lire.","isRealCase":false}],"alternatives":[{"slug":"linux-find","note":"Pour chercher des fichiers selon leur nom, leur taille ou leur date dans toute une arborescence."},{"slug":"linux-du","note":"Pour savoir combien de place occupe un dossier."}],"sources":[{"title":"ls(1)","url":"https://man7.org/linux/man-pages/man1/ls.1.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-find","name":"find","platform":"linux","shell":"bash","difficulty":"intermediate","requiresAdmin":false,"summary":"Cherche des fichiers dans une arborescence selon leur nom, leur type, leur taille, leur date ou leurs droits.","history":"Apparue dans Unix Version 5 (1974). La version GNU (findutils) ajoute -delete, -printf et de nombreux tests.","internals":"find parcourt récursivement l’arborescence et évalue, pour chaque entrée, une expression de gauche à droite. Les actions (-print, -exec, -delete) ne s’appliquent qu’aux entrées qui satisfont les tests qui les précèdent.","syntax":"find [chemin…] [tests] [actions]","why":"Retrouver un fichier de configuration, les gros fichiers qui remplissent un disque ou les fichiers modifiés juste avant une panne, sans tout parcourir à la main.","whenToUse":"Pour une recherche par critères (taille, date, nom). Pour lister un seul dossier, ls suffit. Pour chercher du texte dans des fichiers, utiliser grep -r.","context":"Disponible partout. Les dossiers que vous ne pouvez pas lire produisent des erreurs « Permission denied » sans arrêter la recherche.","riskLevel":"high","risks":[{"level":"none","text":"Sans action, find ne fait que lister."},{"level":"high","text":"Avec -delete ou -exec rm, find supprime tout ce qui correspond, sans corbeille. Un test mal placé (par exemple -delete avant -name) supprime tout le chemin parcouru."}],"bestPractices":["Toujours lancer d’abord la même commande avec -print, relire la liste, puis seulement ajouter -delete.","Placer -delete en dernier dans l’expression.","Limiter la profondeur avec -maxdepth et rester sur un seul système de fichiers avec -xdev.","Rediriger les erreurs de droits (2>/dev/null) seulement après avoir vérifié qu’elles ne cachent rien d’important."],"commonErrors":[{"error":"find: paths must precede expression","cause":"Un motif comme *.log non protégé a été développé par le shell avant d’arriver à find.","fix":"Mettre le motif entre guillemets : find . -name \"*.log\"."},{"error":"Tout le dossier a disparu après un find -delete","cause":"-delete était placé avant le test -name, donc appliqué à toutes les entrées.","fix":"Restaurer depuis la sauvegarde. À l’avenir : tester avec -print, et -delete toujours en dernier."}],"parameters":[{"flag":"-name motif","description":"Nom correspondant au motif (sensible à la casse ; -iname pour l’ignorer).","riskLevel":"none"},{"flag":"-type f|d","description":"Seulement les fichiers (f) ou les répertoires (d).","riskLevel":"none"},{"flag":"-size +100M","description":"Fichiers de plus de 100 Mio (- pour « moins de »).","riskLevel":"none"},{"flag":"-mtime -1","description":"Modifiés il y a moins d’un jour (+7 : il y a plus de 7 jours).","riskLevel":"none"},{"flag":"-xdev","description":"Ne descend pas dans les autres systèmes de fichiers montés.","riskLevel":"none"},{"flag":"-exec cmd {} +","description":"Exécute une commande sur les fichiers trouvés. Le risque est celui de la commande lancée.","riskLevel":"medium"},{"flag":"-delete","description":"Supprime les entrées trouvées, définitivement.","riskLevel":"high"}],"examples":[{"title":"Trouver ce qui remplit la partition racine","code":"sudo find / -xdev -type f -size +500M -exec ls -lh {} + 2>/dev/null","explanation":"-xdev reste sur la partition concernée ; ls -lh affiche taille et date des gros fichiers pour décider quoi faire.","isRealCase":true},{"title":"Purger des journaux applicatifs de plus de 30 jours, en deux temps","code":"find /var/log/monapp -name \"*.log.gz\" -mtime +30 -print\n# relire la liste, puis :\nfind /var/log/monapp -name \"*.log.gz\" -mtime +30 -delete","explanation":"La première commande montre exactement ce qui serait supprimé. La seconde ne change que l’action, placée en dernier.","isRealCase":false}],"alternatives":[{"slug":"linux-ls","note":"Pour regarder un seul dossier."},{"slug":"linux-du","note":"Pour trouver quel dossier occupe le plus de place, avant de chercher les fichiers."}],"sources":[{"title":"find(1)","url":"https://man7.org/linux/man-pages/man1/find.1.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-chmod","name":"chmod","platform":"linux","shell":"bash","difficulty":"beginner","requiresAdmin":false,"summary":"Modifie les droits de lecture, d’écriture et d’exécution d’un fichier ou d’un répertoire.","history":"Présente depuis la première version d’Unix. La notation symbolique (u+x) a été ajoutée pour éviter de calculer les valeurs octales.","internals":"chmod appelle chmod() ou fchmodat() pour réécrire le champ mode de l’inode : trois triplets rwx (propriétaire, groupe, autres) et les bits spéciaux setuid, setgid et sticky.","syntax":"chmod [options] mode fichier…   (mode : u+x, g-w, o=r ou 750)","why":"Les droits décident qui peut lire un secret, modifier une configuration ou lancer un script. Un script sans x ne s’exécute pas ; une clé SSH lisible par tous est refusée par ssh.","whenToUse":"Pour rendre un script exécutable, protéger un fichier sensible ou corriger un « Permission denied » dont la cause est comprise. Si c’est le propriétaire qui est faux, utiliser chown.","context":"Seul le propriétaire du fichier (ou root) peut en changer les droits.","riskLevel":"medium","risks":[{"level":"medium","text":"chmod 777 rend un fichier modifiable par n’importe quel utilisateur ou service compromis : porte ouverte à l’injection de code."},{"level":"medium","text":"chmod -R sur un mauvais chemin change d’un coup les droits de milliers de fichiers ; il n’existe pas d’annulation."}],"bestPractices":["Préférer la notation symbolique (u+x) qui ne touche que ce qui est demandé.","Ne jamais « réparer » un problème avec 777 : chercher qui a besoin de quel droit.","Clés privées et secrets : 600. Scripts : 750 ou 755. Répertoires partagés : 2770 (setgid) plutôt que 777.","Avant un -R, lister ce qui sera touché avec find chemin | head."],"commonErrors":[{"error":"Permissions 0644 for id_rsa are too open","cause":"ssh refuse une clé privée lisible par d’autres que son propriétaire.","fix":"chmod 600 ~/.ssh/id_rsa"},{"error":"bash: ./script.sh: Permission denied","cause":"Le bit x manque.","fix":"chmod u+x script.sh (ou lancer bash script.sh pour un test ponctuel)."}],"parameters":[{"flag":"u+x / g-w / o=","description":"Ajoute, retire ou fixe un droit pour le propriétaire (u), le groupe (g), les autres (o).","riskLevel":"low"},{"flag":"750","description":"Notation octale : 7=rwx, 5=r-x, 0=--- (propriétaire, groupe, autres).","riskLevel":"low"},{"flag":"-R","description":"Récursif : s’applique à tout le contenu du répertoire.","riskLevel":"medium"},{"flag":"--reference=fichier","description":"Copie les droits d’un fichier de référence.","riskLevel":"low"}],"examples":[{"title":"Rendre un script exécutable par son propriétaire seulement","code":"chmod u+x deploy.sh && ls -l deploy.sh","explanation":"u+x n’ajoute que l’exécution pour le propriétaire ; ls -l permet de vérifier le résultat.","isRealCase":false},{"title":"Protéger un fichier de secrets","code":"chmod 600 /etc/monapp/secrets.env","explanation":"Lecture et écriture pour le propriétaire, rien pour les autres. Vérifier ensuite que le service tourne bien sous ce propriétaire.","isRealCase":true}],"alternatives":[{"slug":"linux-chown","note":"Quand le problème vient du propriétaire ou du groupe, pas des droits."}],"sources":[{"title":"chmod(1)","url":"https://man7.org/linux/man-pages/man1/chmod.1.html","publisher":"man7.org"},{"title":"chmod(2)","url":"https://man7.org/linux/man-pages/man2/chmod.2.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-chown","name":"chown","platform":"linux","shell":"bash","difficulty":"intermediate","requiresAdmin":true,"summary":"Change le propriétaire et le groupe d’un fichier ou d’un répertoire.","history":"Présente depuis les premiers Unix. Réservée à root sur Linux pour empêcher un utilisateur de contourner les quotas en « donnant » ses fichiers.","internals":"chown appelle chown() ou lchown() pour réécrire l’uid et le gid de l’inode. Changer le propriétaire efface les bits setuid et setgid par sécurité.","syntax":"sudo chown [options] utilisateur[:groupe] fichier…","why":"Un service tourne sous un compte dédié (www-data, postgres). S’il ne possède pas ses fichiers, il ne peut ni les lire ni écrire ses journaux, et il échoue souvent avec un message peu clair.","whenToUse":"Après avoir copié des fichiers en root pour un service, ou restauré une sauvegarde. Si le propriétaire est bon mais les droits insuffisants, utiliser chmod.","context":"Nécessite root (sudo). Le compte et le groupe doivent exister (id nom pour vérifier).","riskLevel":"high","risks":[{"level":"medium","text":"Donner un fichier sensible à un service exposé lui permet de le modifier en cas de compromission."},{"level":"high","text":"chown -R sur / ou /usr casse sudo, ssh et de nombreux services : le système peut devenir inutilisable."}],"bestPractices":["Vérifier le chemin avec ls -ld avant un -R.","Préciser le groupe explicitement (user:group) pour ne pas dépendre du comportement par défaut.","Ne jamais utiliser -R sur un chemin contenant une variable non vérifiée."],"commonErrors":[{"error":"chown: changing ownership: Operation not permitted","cause":"Commande lancée sans root.","fix":"Relancer avec sudo, si le changement est justifié."},{"error":"chown: invalid user","cause":"Le compte n’existe pas, ou une faute de frappe.","fix":"Vérifier avec id nom ou getent passwd nom."}],"parameters":[{"flag":"user:group","description":"Nouveau propriétaire et groupe ; :group seul ne change que le groupe.","riskLevel":"medium"},{"flag":"-R","description":"Récursif sur tout le contenu.","riskLevel":"high"},{"flag":"--from=ancien","description":"Ne change que les fichiers appartenant à ce propriétaire : limite les dégâts d’un -R.","riskLevel":"low"},{"flag":"-h","description":"Agit sur le lien symbolique lui-même, pas sur sa cible.","riskLevel":"low"}],"examples":[{"title":"Rendre le dossier d’upload à son service web","code":"ls -ld /srv/site/uploads\nsudo chown -R www-data:www-data /srv/site/uploads","explanation":"Le service web (www-data) doit pouvoir écrire les fichiers envoyés. On vérifie le chemin avant le -R.","isRealCase":true}],"alternatives":[{"slug":"linux-chmod","note":"Quand le propriétaire est correct mais que les droits sont insuffisants."}],"sources":[{"title":"chown(1)","url":"https://man7.org/linux/man-pages/man1/chown.1.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-ps","name":"ps","platform":"linux","shell":"bash","difficulty":"beginner","requiresAdmin":false,"summary":"Affiche les processus en cours : identifiant (PID), propriétaire, consommation CPU et mémoire, commande lancée.","history":"Présente depuis Unix V4. Linux accepte deux syntaxes héritées : BSD (ps aux) et System V (ps -ef).","internals":"ps lit /proc/<pid>/stat, status et cmdline pour chaque processus. C’est une photographie à un instant donné, pas un suivi continu.","syntax":"ps aux   |   ps -eo pid,user,%cpu,%mem,cmd --sort=-%cpu","why":"Savoir ce qui tourne réellement : un service est-il lancé, sous quel compte, et qui consomme le processeur ou la mémoire ?","whenToUse":"Quand une machine est lente, pour vérifier qu’un service tourne, ou trouver le PID à arrêter. Pour suivre l’évolution dans le temps, utiliser top ou htop.","context":"Aucun droit particulier pour lire la liste ; certains détails des processus d’autres utilisateurs peuvent être masqués (option hidepid de /proc).","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule. Attention seulement à ne pas copier publiquement une sortie qui contiendrait des mots de passe passés en arguments."}],"bestPractices":["Trier par consommation : ps aux --sort=-%mem | head.","Pour chercher un processus, préférer pgrep -a nom à ps | grep, qui se trouve lui-même."],"commonErrors":[],"parameters":[{"flag":"aux","description":"Tous les processus de tous les utilisateurs, avec CPU et mémoire (syntaxe BSD).","riskLevel":"none"},{"flag":"-ef","description":"Tous les processus avec le PID parent (syntaxe System V), utile pour voir qui a lancé quoi.","riskLevel":"none"},{"flag":"-o colonnes","description":"Choisit les colonnes affichées.","riskLevel":"none"},{"flag":"--sort=-%cpu","description":"Trie par CPU décroissant.","riskLevel":"none"}],"examples":[{"title":"Les cinq processus qui consomment le plus de mémoire","code":"ps aux --sort=-%mem | head -6","explanation":"La colonne RSS est la mémoire physique réellement utilisée, en Kio. C’est la première chose à regarder quand le noyau tue des processus (OOM).","isRealCase":true}],"alternatives":[{"slug":"linux-kill","note":"Pour arrêter un processus une fois identifié."},{"slug":"linux-systemctl","note":"Pour l’état d’un service géré par systemd, avec ses derniers journaux."}],"sources":[{"title":"ps(1)","url":"https://man7.org/linux/man-pages/man1/ps.1.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-kill","name":"kill","platform":"linux","shell":"bash","difficulty":"intermediate","requiresAdmin":false,"summary":"Envoie un signal à un processus, le plus souvent pour lui demander de s’arrêter.","history":"Présente depuis Unix V3. Le nom trompe : kill envoie n’importe quel signal, pas seulement l’arrêt.","internals":"kill appelle kill(pid, signal). SIGTERM (15) demande un arrêt propre que le programme peut intercepter ; SIGKILL (9) est appliqué par le noyau, sans que le programme puisse réagir ni nettoyer.","syntax":"kill [-signal] PID…","why":"Arrêter un programme bloqué ou demander à un service de relire sa configuration (SIGHUP), sans redémarrer la machine.","whenToUse":"Pour un processus qui n’est pas géré par systemd. Pour un service, préférer systemctl stop ou restart, qui respecte ses dépendances et le relance si nécessaire.","context":"On ne peut signaler que ses propres processus ; root peut signaler tous les processus.","riskLevel":"high","risks":[{"level":"medium","text":"SIGTERM arrête le programme : les utilisateurs connectés perdent leur session."},{"level":"high","text":"SIGKILL (-9) empêche tout nettoyage : fichiers temporaires, verrous et écritures en cours peuvent rester incohérents, jusqu’à corrompre une base de données."}],"bestPractices":["Toujours essayer SIGTERM d’abord, attendre quelques secondes, et n’utiliser -9 qu’en dernier recours.","Vérifier le PID avec ps -p PID -o pid,cmd juste avant : un PID peut être réutilisé par un autre programme.","Ne jamais envoyer -9 à une base de données : utiliser son propre arrêt."],"commonErrors":[{"error":"kill: (1234) - Operation not permitted","cause":"Le processus appartient à un autre utilisateur.","fix":"Vérifier le propriétaire avec ps ; utiliser sudo seulement si l’arrêt est justifié."},{"error":"Le processus est toujours là après kill -9","cause":"Il est bloqué dans le noyau (état D, souvent une entrée-sortie disque ou réseau) ou c’est un zombie (état Z) déjà mort.","fix":"Pour D : chercher le disque ou le partage réseau en cause. Pour Z : c’est le parent qui doit le récupérer."}],"parameters":[{"flag":"-15 / -TERM","description":"Demande d’arrêt propre (signal par défaut).","riskLevel":"medium"},{"flag":"-1 / -HUP","description":"Beaucoup de services relisent leur configuration à la réception de ce signal.","riskLevel":"low"},{"flag":"-9 / -KILL","description":"Arrêt immédiat par le noyau, sans nettoyage.","riskLevel":"high"},{"flag":"-l","description":"Liste les signaux disponibles.","riskLevel":"none"}],"examples":[{"title":"Arrêter proprement un script resté bloqué","code":"pgrep -a rapport.py\nkill 48211\nsleep 5; ps -p 48211 || echo \"arrêté\"","explanation":"On identifie le PID, on demande l’arrêt, puis on vérifie. Ce n’est que si le processus est toujours là qu’on envisage -9.","isRealCase":false}],"alternatives":[{"slug":"linux-systemctl","note":"Pour arrêter ou redémarrer un service : systemd gère l’ordre, les dépendances et le redémarrage."},{"slug":"linux-ps","note":"Pour identifier le bon PID avant d’agir."}],"sources":[{"title":"kill(1)","url":"https://man7.org/linux/man-pages/man1/kill.1.html","publisher":"man7.org"},{"title":"signal(7)","url":"https://man7.org/linux/man-pages/man7/signal.7.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-df","name":"df","platform":"linux","shell":"bash","difficulty":"beginner","requiresAdmin":false,"summary":"Affiche l’espace utilisé et disponible sur chaque système de fichiers monté.","history":"Abréviation de « disk free », présente depuis Unix V1.","internals":"df interroge le noyau (statfs) pour chaque point de montage. Il compte les blocs alloués, y compris ceux de fichiers supprimés mais encore ouverts par un programme.","syntax":"df [-h] [-i] [chemin]","why":"Un disque plein fait échouer des services sans message clair : base de données en lecture seule, journaux qui ne s’écrivent plus, mises à jour impossibles. df dit en une seconde si c’est le cas.","whenToUse":"Dès qu’un service échoue de façon inexpliquée, ou qu’on voit « No space left on device ». Pour savoir quel dossier occupe la place, enchaîner avec du.","context":"Aucun droit particulier.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule."}],"bestPractices":["Regarder aussi les inodes (df -i) : un disque peut être « plein » de petits fichiers alors qu’il reste des gigaoctets.","Si df et du ne sont pas d’accord, chercher les fichiers supprimés encore ouverts : sudo lsof +L1.","Environ 5 % de chaque partition ext4 sont réservés à root : un utilisateur peut voir 100 % alors que root peut encore écrire."],"commonErrors":[{"error":"df indique 100 % mais du ne trouve pas les fichiers","cause":"Un fichier supprimé est encore ouvert par un processus (souvent un journal) : l’espace n’est libéré qu’à sa fermeture.","fix":"sudo lsof +L1 pour trouver le processus, puis le redémarrer proprement."}],"parameters":[{"flag":"-h","description":"Tailles lisibles (Go, Mo).","riskLevel":"none"},{"flag":"-i","description":"Affiche les inodes au lieu des blocs.","riskLevel":"none"},{"flag":"-T","description":"Affiche le type de système de fichiers (ext4, xfs, tmpfs…).","riskLevel":"none"}],"examples":[{"title":"Un service PostgreSQL refuse d’écrire","code":"df -h /var/lib/postgresql\ndf -i /var/lib/postgresql","explanation":"On vérifie la partition qui contient les données, en blocs puis en inodes. Si elle est pleine, du dira quoi nettoyer.","isRealCase":true}],"alternatives":[{"slug":"linux-du","note":"Pour trouver quel dossier occupe la place une fois la partition pleine identifiée."}],"sources":[{"title":"df(1)","url":"https://man7.org/linux/man-pages/man1/df.1.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-du","name":"du","platform":"linux","shell":"bash","difficulty":"beginner","requiresAdmin":false,"summary":"Calcule l’espace disque occupé par des fichiers et des dossiers.","history":"Abréviation de « disk usage », présente depuis Unix V1.","internals":"du parcourt l’arborescence et additionne les blocs réellement alloués à chaque fichier (stat), ce qui peut différer de la taille apparente pour les fichiers creux.","syntax":"du [-sh] [--max-depth=N] chemin…","why":"Après df, qui dit quelle partition est pleine, du dit quel dossier est responsable. On peut alors nettoyer la vraie cause au lieu de supprimer au hasard.","whenToUse":"Pour descendre dossier par dossier jusqu’à la source d’un disque plein. Pour l’état global des partitions, df.","context":"Il faut le droit de lire les dossiers parcourus : utilisez sudo pour les dossiers système, sinon les totaux seront sous-estimés.","riskLevel":"low","risks":[{"level":"none","text":"Lecture seule."},{"level":"low","text":"Sur une très grosse arborescence ou un partage réseau, du peut charger fortement les disques pendant plusieurs minutes."}],"bestPractices":["Descendre niveau par niveau : du -h --max-depth=1 /var | sort -h.","Ajouter -x pour ne pas compter les autres partitions montées dans le dossier."],"commonErrors":[],"parameters":[{"flag":"-s","description":"Un seul total par argument.","riskLevel":"none"},{"flag":"-h","description":"Tailles lisibles.","riskLevel":"none"},{"flag":"--max-depth=1","description":"Un total par sous-dossier direct.","riskLevel":"none"},{"flag":"-x","description":"Reste sur le même système de fichiers.","riskLevel":"none"}],"examples":[{"title":"Trouver le dossier qui remplit /var","code":"sudo du -xh --max-depth=1 /var | sort -h | tail","explanation":"Les plus gros dossiers apparaissent en bas. On recommence sur le plus gros jusqu’à trouver la cause, souvent des journaux ou un cache.","isRealCase":true}],"alternatives":[{"slug":"linux-df","note":"Pour savoir d’abord quelle partition est pleine."},{"slug":"linux-find","note":"Pour lister directement les plus gros fichiers."}],"sources":[{"title":"du(1)","url":"https://man7.org/linux/man-pages/man1/du.1.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-ip","name":"ip","platform":"linux","shell":"bash","difficulty":"intermediate","requiresAdmin":false,"summary":"Affiche et modifie la configuration réseau : interfaces, adresses, routes et voisins.","history":"Fait partie d’iproute2 (1999), qui remplace ifconfig et route, devenus obsolètes car ils ne voient pas toutes les fonctions du noyau.","internals":"ip dialogue avec le noyau par netlink. Les modifications sont immédiates mais non persistantes : elles disparaissent au redémarrage, la configuration durable étant gérée par NetworkManager, systemd-networkd ou netplan.","syntax":"ip [-br] [-c] address|link|route [show|add|del] …","why":"Un problème réseau commence par trois questions : l’interface est-elle active, a-t-elle une adresse, et par où part le trafic ? ip y répond.","whenToUse":"En lecture, pour tout diagnostic réseau. En écriture, pour un essai temporaire ; la configuration permanente se fait dans l’outil de la distribution.","context":"La lecture ne demande aucun droit ; toute modification demande root.","riskLevel":"high","risks":[{"level":"none","text":"Les commandes show sont en lecture seule."},{"level":"high","text":"ip link set down, ip addr del ou ip route del sur l’interface par laquelle vous êtes connecté coupent votre session SSH : il faut alors un accès console."}],"bestPractices":["Utiliser -br (brief) et -c (couleurs) pour une vue lisible.","Avant une modification à distance, programmer un retour arrière (par exemple avec at ou une commande sleep suivie de la restauration).","Rendre une modification permanente dans l’outil de la distribution, pas dans un script de démarrage."],"commonErrors":[{"error":"RTNETLINK answers: Operation not permitted","cause":"Modification lancée sans root.","fix":"Relancer avec sudo si la modification est voulue."},{"error":"La configuration a disparu après redémarrage","cause":"Les changements faits avec ip sont temporaires.","fix":"Les reporter dans NetworkManager (nmcli), netplan ou systemd-networkd."}],"parameters":[{"flag":"-br a","description":"Une ligne par interface : état et adresses.","riskLevel":"none"},{"flag":"route","description":"Table de routage ; la ligne default indique la passerelle.","riskLevel":"none"},{"flag":"route get 1.1.1.1","description":"Par quelle interface et quelle passerelle partirait un paquet vers cette adresse.","riskLevel":"none"},{"flag":"link set dev X down","description":"Désactive une interface.","riskLevel":"high"},{"flag":"addr add/del","description":"Ajoute ou retire une adresse (temporaire).","riskLevel":"high"}],"examples":[{"title":"Le serveur ne joint plus Internet","code":"ip -br a\nip route\nip route get 1.1.1.1","explanation":"On vérifie dans l’ordre : interface UP avec une adresse, présence d’une route par défaut, puis le chemin réellement choisi.","isRealCase":true}],"alternatives":[{"slug":"linux-ss","note":"Pour voir les connexions et les ports en écoute, pas la configuration des interfaces."},{"slug":"linux-dig","note":"Quand le réseau fonctionne mais que les noms ne se résolvent pas."}],"sources":[{"title":"ip(8)","url":"https://man7.org/linux/man-pages/man8/ip.8.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-ss","name":"ss","platform":"linux","shell":"bash","difficulty":"intermediate","requiresAdmin":false,"summary":"Liste les sockets : ports en écoute et connexions établies, avec le processus associé.","history":"Fait partie d’iproute2 et remplace netstat, plus lent sur les serveurs très chargés.","internals":"ss interroge le noyau par netlink (sock_diag) au lieu de lire /proc/net/tcp, ce qui reste rapide même avec des dizaines de milliers de connexions.","syntax":"ss [-t] [-u] [-l] [-n] [-p] [filtre]","why":"Répondre à « mon service écoute-t-il vraiment ? », « sur quelle adresse ? » et « qui occupe déjà ce port ? ».","whenToUse":"Quand un service ne répond pas, qu’un démarrage échoue avec « Address already in use », ou pour compter les connexions vers une base.","context":"Lecture sans droit ; l’option -p (processus) ne montre ceux des autres utilisateurs qu’avec sudo.","riskLevel":"low","risks":[{"level":"none","text":"Lecture seule."},{"level":"low","text":"L’option -K ferme des connexions : à ne pas utiliser sans raison précise."}],"bestPractices":["La combinaison la plus utile : sudo ss -tlnp (TCP, en écoute, numérique, processus).","Regarder l’adresse d’écoute : 127.0.0.1 n’est joignable que localement, 0.0.0.0 ou [::] depuis l’extérieur."],"commonErrors":[{"error":"Le service écoute mais reste injoignable depuis un autre poste","cause":"Il écoute sur 127.0.0.1, ou un pare-feu bloque le port.","fix":"Changer l’adresse d’écoute dans sa configuration, ou ouvrir le port dans le pare-feu (ufw, firewalld)."}],"parameters":[{"flag":"-t / -u","description":"TCP / UDP.","riskLevel":"none"},{"flag":"-l","description":"Seulement les sockets en écoute.","riskLevel":"none"},{"flag":"-n","description":"Adresses et ports en chiffres, sans résolution de noms (plus rapide et sans ambiguïté).","riskLevel":"none"},{"flag":"-p","description":"Processus propriétaire de chaque socket.","riskLevel":"none"},{"flag":"-K","description":"Ferme les sockets correspondant au filtre (root).","riskLevel":"low"}],"examples":[{"title":"« Address already in use » au démarrage de nginx","code":"sudo ss -tlnp 'sport = :80'","explanation":"Montre quel processus occupe déjà le port 80 (souvent une autre instance ou Apache).","isRealCase":true}],"alternatives":[{"slug":"linux-ip","note":"Pour la configuration des interfaces et des routes."},{"slug":"linux-ps","note":"Pour en savoir plus sur le processus trouvé."}],"sources":[{"title":"ss(8)","url":"https://man7.org/linux/man-pages/man8/ss.8.html","publisher":"man7.org"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-dig","name":"dig","platform":"linux","shell":"bash","difficulty":"intermediate","requiresAdmin":false,"summary":"Interroge des serveurs DNS et affiche leur réponse détaillée.","history":"Fourni avec BIND (Internet Systems Consortium). « Domain Information Groper ».","internals":"dig envoie une requête DNS (UDP 53, ou TCP si la réponse est trop longue) et affiche la réponse brute : code de retour, enregistrements, durée de validité (TTL) et serveur qui a répondu.","syntax":"dig [@serveur] nom [type] [+short]","why":"Beaucoup de « pannes réseau » sont des pannes de résolution de noms. dig sépare les deux : si dig répond mais que l’application échoue, le problème est ailleurs.","whenToUse":"Quand un site « ne marche pas » alors que l’adresse IP répond, après un changement d’enregistrement DNS, ou pour comparer deux serveurs DNS.","context":"Paquet dnsutils (Debian, Ubuntu) ou bind-utils (Red Hat). Aucun droit particulier.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule."}],"bestPractices":["Comparer le résolveur local et un résolveur public : dig nom puis dig @1.1.1.1 nom.","Lire le statut : NXDOMAIN (le nom n’existe pas) n’a pas la même cause que SERVFAIL (le serveur n’a pas pu répondre).","Après une modification, regarder le TTL : il indique combien de temps les caches garderont l’ancienne valeur."],"commonErrors":[{"error":"dig: command not found","cause":"Paquet non installé.","fix":"sudo apt install dnsutils (ou dnf install bind-utils)."}],"parameters":[{"flag":"@serveur","description":"Interroge ce serveur au lieu du résolveur configuré.","riskLevel":"none"},{"flag":"A / AAAA / MX / TXT","description":"Type d’enregistrement demandé.","riskLevel":"none"},{"flag":"+short","description":"Seulement la réponse.","riskLevel":"none"},{"flag":"+trace","description":"Suit la résolution depuis les serveurs racine : montre où elle casse.","riskLevel":"none"}],"examples":[{"title":"Le site répond par son IP mais pas par son nom","code":"dig intranet.exemple.fr\ndig @1.1.1.1 intranet.exemple.fr","explanation":"Si le résolveur interne répond et pas le public, c’est un nom interne normal. Si aucun ne répond, l’enregistrement manque.","isRealCase":true}],"alternatives":[{"slug":"linux-ip","note":"Quand même les adresses IP ne répondent pas : le problème est sous le DNS."},{"slug":"windows-nslookup","note":"Équivalent disponible sous Windows."}],"sources":[{"title":"dig(1)","url":"https://bind9.readthedocs.io/en/latest/manpages.html#dig-dns-lookup-utility","publisher":"ISC"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"linux-tar","name":"tar","platform":"linux","shell":"bash","difficulty":"beginner","requiresAdmin":false,"summary":"Regroupe des fichiers dans une archive (souvent compressée) ou en extrait le contenu.","history":"« Tape ARchiver » : créé en 1979 pour écrire sur bande magnétique. Toujours le format standard de distribution sous Unix.","internals":"tar concatène les fichiers avec un en-tête par fichier (nom, droits, propriétaire, dates). La compression (gzip, xz, zstd) est appliquée au flux complet.","syntax":"tar -czf archive.tar.gz chemin…   |   tar -xzf archive.tar.gz -C destination","why":"Sauvegarder une configuration avant de la modifier, ou déplacer une arborescence en conservant droits et propriétaires.","whenToUse":"Avant toute modification importante d’un dossier de configuration, ou pour transférer un ensemble de fichiers. Pour une vraie stratégie de sauvegarde (incrémentale, chiffrée), utiliser un outil dédié.","context":"Aucun droit particulier, sauf pour lire des fichiers système ou restaurer les propriétaires d’origine (root).","riskLevel":"medium","risks":[{"level":"low","text":"Créer une archive lit seulement les fichiers."},{"level":"medium","text":"Extraire écrase sans prévenir les fichiers de même nom dans la destination. Une archive venue d’ailleurs peut contenir des chemins inattendus."}],"bestPractices":["Lister le contenu avant d’extraire : tar -tzf archive.tar.gz | head.","Toujours extraire dans un dossier vide choisi avec -C.","Dater les archives de sauvegarde : config-$(date +%F).tar.gz."],"commonErrors":[{"error":"tar: Removing leading `/' from member names","cause":"Message normal : tar enregistre des chemins relatifs pour ne pas écraser le système à l’extraction.","fix":"Rien à faire ; extraire avec -C / seulement si c’est vraiment voulu."}],"parameters":[{"flag":"-c / -x / -t","description":"Créer, extraire ou lister.","riskLevel":"medium"},{"flag":"-z / -J / --zstd","description":"Compression gzip, xz ou zstd.","riskLevel":"none"},{"flag":"-f fichier","description":"Nom de l’archive (obligatoire en pratique).","riskLevel":"none"},{"flag":"-C dossier","description":"Se place dans ce dossier avant d’agir.","riskLevel":"low"},{"flag":"-p","description":"Conserve les droits exacts à l’extraction.","riskLevel":"low"}],"examples":[{"title":"Sauvegarder la configuration nginx avant de la modifier","code":"sudo tar -czf ~/nginx-$(date +%F).tar.gz /etc/nginx\ntar -tzf ~/nginx-$(date +%F).tar.gz | head","explanation":"Une archive datée permet de revenir en arrière en une commande ; la liste vérifie qu’elle contient bien les fichiers.","isRealCase":true}],"alternatives":[{"slug":"linux-find","note":"Pour sélectionner précisément les fichiers à archiver (find … -print0 | tar --null -T -)."}],"sources":[{"title":"GNU tar manual","url":"https://www.gnu.org/software/tar/manual/tar.html","publisher":"GNU"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-ipconfig","name":"ipconfig","platform":"windows","shell":"cmd","difficulty":"beginner","requiresAdmin":false,"summary":"Affiche la configuration IP des cartes réseau et gère le cache DNS et les baux DHCP.","history":"Présente depuis Windows NT. Remplace winipcfg, l’outil graphique de Windows 9x.","internals":"ipconfig interroge la pile TCP/IP et le client DHCP. /flushdns vide le cache du service Client DNS (Dnscache) ; /renew redemande une adresse au serveur DHCP.","syntax":"ipconfig [/all] [/release] [/renew] [/flushdns] [/displaydns]","why":"Savoir en dix secondes si le poste a une adresse valide, une passerelle et des serveurs DNS. Une adresse en 169.254.x.x signifie qu’aucun serveur DHCP n’a répondu.","whenToUse":"Au tout début d’un diagnostic réseau, et après un changement de réseau ou de DNS. Pour des modifications durables, utiliser les paramètres réseau ou PowerShell (Set-NetIPAddress).","context":"Invite de commandes ou PowerShell. La lecture ne demande aucun droit ; /release, /renew et /flushdns fonctionnent sans droits d’administrateur sur les versions récentes.","riskLevel":"medium","risks":[{"level":"none","text":"ipconfig et ipconfig /all sont en lecture seule."},{"level":"low","text":"/flushdns oblige seulement à refaire les résolutions DNS : sans danger."},{"level":"medium","text":"/release coupe immédiatement le réseau de la carte : en bureau à distance, vous perdez la session jusqu’au /renew, que vous ne pourrez plus lancer."}],"bestPractices":["Commencer par ipconfig /all : il montre aussi le serveur DHCP, les DNS et l’adresse physique (MAC).","Ne jamais lancer /release à distance : enchaîner « ipconfig /release && ipconfig /renew » sur une seule ligne si c’est indispensable."],"commonErrors":[{"error":"Adresse IPv4 en 169.254.x.x (APIPA)","cause":"Le poste n’a reçu aucune réponse DHCP : câble, Wi-Fi, VLAN ou serveur DHCP en panne.","fix":"Vérifier la connexion physique, puis ipconfig /renew ; si l’échec persiste, regarder le serveur DHCP."}],"parameters":[{"flag":"/all","description":"Configuration complète : DHCP, DNS, passerelle, adresse MAC, bail.","riskLevel":"none"},{"flag":"/flushdns","description":"Vide le cache DNS local.","riskLevel":"low"},{"flag":"/displaydns","description":"Affiche le cache DNS local.","riskLevel":"none"},{"flag":"/renew","description":"Redemande une adresse au serveur DHCP.","riskLevel":"low"},{"flag":"/release","description":"Rend l’adresse DHCP : la carte n’a plus d’adresse.","riskLevel":"medium"}],"examples":[{"title":"Le poste « n’a plus Internet »","code":"ipconfig /all","explanation":"On lit l’adresse IPv4 (169.254 = pas de DHCP), la passerelle par défaut (vide = pas de route) et les serveurs DNS.","isRealCase":true},{"title":"Un site a changé d’adresse mais le poste va encore sur l’ancienne","code":"ipconfig /flushdns\nnslookup intranet.exemple.fr","explanation":"On vide le cache local, puis on vérifie la nouvelle réponse DNS.","isRealCase":false}],"alternatives":[{"slug":"windows-ping","note":"Pour tester la connectivité une fois la configuration vérifiée."},{"slug":"linux-ip","note":"Équivalent sous Linux."}],"sources":[{"title":"ipconfig (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/ipconfig","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-ping","name":"ping","platform":"windows","shell":"cmd","difficulty":"beginner","requiresAdmin":false,"summary":"Vérifie qu’une machine répond sur le réseau et mesure le temps d’aller-retour.","history":"Écrit par Mike Muuss en 1983, par analogie avec le sonar. Présent sur tous les systèmes.","internals":"ping envoie des paquets ICMP Echo Request et attend des Echo Reply. Beaucoup de pare-feu bloquent ICMP : une absence de réponse ne prouve pas que la machine est éteinte.","syntax":"ping [-n nombre] [-t] [-4|-6] destination","why":"Séparer les couches d’un problème : la passerelle répond-elle ? une IP publique ? un nom ? Chaque réponse élimine une famille de causes.","whenToUse":"Dans l’ordre : passerelle, puis IP publique (1.1.1.1), puis un nom. Pour savoir où le trajet s’arrête, utiliser tracert.","context":"Aucun droit particulier. Le pare-feu Windows bloque par défaut les réponses ping entrantes : un poste Windows peut ne pas répondre tout en étant joignable.","riskLevel":"none","risks":[{"level":"none","text":"Envoie seulement quelques petits paquets."}],"bestPractices":["Tester par étapes : passerelle → 1.1.1.1 → nom de domaine.","Si l’IP répond et pas le nom, le problème est le DNS (nslookup).","Utiliser -t pour surveiller une coupure intermittente, et Ctrl+C pour les statistiques."],"commonErrors":[{"error":"Délai d’attente de la demande dépassé","cause":"Pas de réponse : machine éteinte, route absente, ou ICMP bloqué par un pare-feu.","fix":"Essayer la passerelle, puis un autre test (ouvrir le service, tracert) avant de conclure."},{"error":"Impossible de trouver l’hôte","cause":"Le nom ne se résout pas : problème DNS, pas de connectivité.","fix":"nslookup nom, puis vérifier les DNS dans ipconfig /all."}],"parameters":[{"flag":"-n N","description":"Envoie N paquets (4 par défaut).","riskLevel":"none"},{"flag":"-t","description":"Envoie en continu jusqu’à Ctrl+C.","riskLevel":"none"},{"flag":"-4 / -6","description":"Force IPv4 ou IPv6.","riskLevel":"none"}],"examples":[{"title":"Méthode par couches","code":"ping 192.168.1.1\nping 1.1.1.1\nping www.exemple.fr","explanation":"Passerelle OK mais 1.1.1.1 KO : problème chez le fournisseur ou la box. 1.1.1.1 OK mais le nom KO : problème DNS.","isRealCase":true}],"alternatives":[{"slug":"windows-tracert","note":"Pour voir à quel routeur le trajet s’arrête."},{"slug":"windows-nslookup","note":"Quand les adresses répondent mais pas les noms."}],"sources":[{"title":"ping (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/ping","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-tracert","name":"tracert","platform":"windows","shell":"cmd","difficulty":"intermediate","requiresAdmin":false,"summary":"Affiche les routeurs traversés jusqu’à une destination et le temps de réponse de chacun.","history":"Version Windows de traceroute (Van Jacobson, 1987).","internals":"tracert envoie des paquets avec une durée de vie (TTL) croissante : 1, 2, 3… Chaque routeur qui décrémente le TTL à zéro renvoie un message ICMP « Time Exceeded », ce qui révèle son adresse.","syntax":"tracert [-d] [-h sauts] destination","why":"Quand ping échoue, savoir si le problème est sur le réseau local, chez le fournisseur ou près de la destination.","whenToUse":"Après un ping en échec ou très lent vers une destination distante. Pour un problème de nom, utiliser nslookup.","context":"Aucun droit particulier. Des étoiles (*) sur une ligne isolée sont normales : certains routeurs ne répondent pas à ces paquets.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule ; génère un trafic très faible."}],"bestPractices":["Ajouter -d pour éviter les résolutions de noms, souvent très lentes.","Ne regarder que la première ligne où tout s’arrête durablement, pas une étoile isolée."],"commonErrors":[],"parameters":[{"flag":"-d","description":"N’affiche pas les noms des routeurs (beaucoup plus rapide).","riskLevel":"none"},{"flag":"-h N","description":"Nombre maximal de sauts (30 par défaut).","riskLevel":"none"}],"examples":[{"title":"Le serveur d’une agence ne répond plus","code":"tracert -d 10.20.0.15","explanation":"Si tout s’arrête après la passerelle locale, regarder le lien VPN ou inter-sites ; si tout s’arrête juste avant le serveur, regarder son pare-feu.","isRealCase":true}],"alternatives":[{"slug":"windows-ping","note":"Pour un simple test de joignabilité."}],"sources":[{"title":"tracert (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/tracert","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-nslookup","name":"nslookup","platform":"windows","shell":"cmd","difficulty":"intermediate","requiresAdmin":false,"summary":"Interroge un serveur DNS pour connaître l’adresse d’un nom (ou le nom d’une adresse).","history":"Fourni avec BIND dans les années 1980, intégré à Windows depuis NT.","internals":"nslookup interroge directement un serveur DNS, sans passer par le cache local de Windows ni par le fichier hosts. Il peut donc répondre différemment d’une application.","syntax":"nslookup [-type=A|MX|TXT] nom [serveur]","why":"Distinguer une panne réseau d’une panne de résolution de noms, et vérifier ce que répond chaque serveur DNS.","whenToUse":"Quand un ping par IP fonctionne mais pas par nom, après une modification DNS, ou pour vérifier les enregistrements d’un domaine Active Directory.","context":"Aucun droit particulier.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule."}],"bestPractices":["Comparer le serveur interne et un serveur public : nslookup nom puis nslookup nom 1.1.1.1.","Si nslookup répond mais pas l’application, vérifier le fichier hosts et vider le cache (ipconfig /flushdns)."],"commonErrors":[{"error":"DNS request timed out","cause":"Le serveur DNS configuré ne répond pas.","fix":"Vérifier l’adresse DNS dans ipconfig /all et la joignabilité de ce serveur."},{"error":"*** Non-existent domain","cause":"Le nom n’existe pas sur ce serveur (NXDOMAIN).","fix":"Vérifier l’orthographe et le suffixe DNS, ou créer l’enregistrement."}],"parameters":[{"flag":"-type=MX","description":"Type d’enregistrement (A, AAAA, MX, TXT, SRV…).","riskLevel":"none"},{"flag":"serveur","description":"Interroge ce serveur DNS au lieu de celui configuré.","riskLevel":"none"}],"examples":[{"title":"Les postes ne trouvent plus le contrôleur de domaine","code":"nslookup -type=SRV _ldap._tcp.dc._msdcs.exemple.local","explanation":"Les postes trouvent les contrôleurs de domaine par ces enregistrements SRV ; s’ils manquent, l’ouverture de session échoue.","isRealCase":true}],"alternatives":[{"slug":"linux-dig","note":"Équivalent plus détaillé sous Linux."},{"slug":"windows-ipconfig","note":"Pour vérifier quels serveurs DNS le poste utilise."}],"sources":[{"title":"nslookup (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/nslookup","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-chkdsk","name":"chkdsk","platform":"windows","shell":"cmd","difficulty":"intermediate","requiresAdmin":true,"summary":"Vérifie la cohérence d’un système de fichiers NTFS et, sur demande, répare les erreurs logiques et repère les secteurs défectueux.","history":"Héritée de MS-DOS. Depuis Windows 8, NTFS corrige beaucoup d’erreurs en ligne et /scan travaille sans démonter le volume.","internals":"chkdsk vérifie la table des fichiers (MFT), les index et les descripteurs de sécurité. /f corrige ces structures ; /r lit en plus chaque secteur du disque pour déplacer les données lisibles hors des secteurs défectueux.","syntax":"chkdsk [volume:] [/scan] [/f] [/r] [/spotfix]","why":"Des fichiers qui disparaissent, des erreurs « fichier ou répertoire endommagé » ou un démarrage qui s’arrête sur une erreur disque peuvent venir d’une incohérence du système de fichiers.","whenToUse":"Après une coupure de courant, sur un message de corruption ou un événement Ntfs dans le journal. Si le disque lui-même est en train de mourir (bruits, SMART en alerte), sauvegarder d’abord : /r le sollicite fortement.","context":"Invite de commandes en administrateur. Le volume système ne peut pas être réparé à chaud : la réparation est programmée au prochain redémarrage.","riskLevel":"high","risks":[{"level":"none","text":"/scan analyse sans rien modifier."},{"level":"medium","text":"/f peut supprimer des fichiers trop endommagés (récupérés dans found.000) et rend le volume indisponible pendant la réparation."},{"level":"high","text":"/r lit tout le disque : sur un disque mécanique défaillant, cela peut durer des heures et précipiter la panne avant la sauvegarde."}],"bestPractices":["Commencer par chkdsk C: /scan, qui ne modifie rien.","Sauvegarder avant /f ou /r si les données comptent.","Sur un SSD, /r n’a pas de sens (le contrôleur gère les cellules) : se contenter de /f.","Lire ensuite le résultat dans l’Observateur d’événements (source Chkdsk ou Wininit)."],"commonErrors":[{"error":"Chkdsk ne peut pas s’exécuter car le volume est utilisé par un autre processus","cause":"Volume système ou fichiers ouverts.","fix":"Accepter la planification au prochain redémarrage (O), puis redémarrer."}],"parameters":[{"flag":"/scan","description":"Analyse en ligne, sans réparer.","riskLevel":"none"},{"flag":"/spotfix","description":"Corrige rapidement les erreurs déjà repérées par /scan.","riskLevel":"medium"},{"flag":"/f","description":"Corrige les erreurs du système de fichiers.","riskLevel":"medium"},{"flag":"/r","description":"Inclut /f et recherche les secteurs défectueux (long).","riskLevel":"high"}],"examples":[{"title":"Erreur Ntfs 55 dans le journal Système","code":"chkdsk C: /scan\nchkdsk C: /spotfix","explanation":"L’analyse confirme la corruption sans rien toucher ; /spotfix corrige seulement les points trouvés, avec une indisponibilité de quelques secondes au redémarrage.","isRealCase":true}],"alternatives":[{"slug":"windows-sfc","note":"Quand ce sont les fichiers de Windows qui sont corrompus, pas le système de fichiers."},{"slug":"windows-get-winevent","note":"Pour lire le résultat de chkdsk après un redémarrage."}],"sources":[{"title":"chkdsk (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/chkdsk","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-get-winevent","name":"Get-WinEvent","platform":"windows","shell":"powershell","difficulty":"intermediate","requiresAdmin":false,"summary":"Lit les journaux d’événements Windows depuis PowerShell, avec des filtres précis.","history":"Introduite avec PowerShell 2.0 (2009). Remplace Get-EventLog, qui ne lit pas les journaux modernes (Applications et services).","internals":"Get-WinEvent utilise l’API Windows Event Log. Avec -FilterHashtable, le filtre est appliqué par le service de journalisation lui-même : bien plus rapide que de tout lire puis filtrer avec Where-Object.","syntax":"Get-WinEvent -FilterHashtable @{LogName='System'; Level=1,2; StartTime=(Get-Date).AddDays(-1)}","why":"Lire les journaux sans interface graphique, à distance ou dans un script, et ne garder que les événements utiles au diagnostic.","whenToUse":"Pour un diagnostic à distance, sur plusieurs postes, ou pour extraire un extrait à joindre à un diagnostic. Pour une première exploration, l’Observateur d’événements reste plus confortable.","context":"PowerShell. Le journal Sécurité exige les droits d’administrateur ; Système et Application sont lisibles par tous.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule. Les journaux peuvent contenir des noms d’utilisateurs et de machines : relisez avant de les partager."}],"bestPractices":["Toujours filtrer avec -FilterHashtable, jamais Get-WinEvent | Where-Object sur un gros journal.","Limiter le nombre avec -MaxEvents.","Ajouter StartTime pour ne garder que la période de l’incident."],"commonErrors":[{"error":"Aucun événement ne correspond aux critères de sélection","cause":"Message normal quand le filtre ne trouve rien (et non une erreur de la commande).","fix":"Élargir la période ou les niveaux ; ajouter -ErrorAction SilentlyContinue dans un script."}],"parameters":[{"flag":"LogName","description":"Journal : System, Application, Security, ou un journal Applications et services.","riskLevel":"none"},{"flag":"Level","description":"1 critique, 2 erreur, 3 avertissement, 4 information.","riskLevel":"none"},{"flag":"Id","description":"Identifiant d’événement (41, 6008, 1074…).","riskLevel":"none"},{"flag":"-MaxEvents N","description":"Ne renvoie que les N plus récents.","riskLevel":"none"},{"flag":"-ComputerName","description":"Lit les journaux d’un autre poste (droits et pare-feu nécessaires).","riskLevel":"none"}],"examples":[{"title":"Redémarrages inattendus de la dernière semaine","code":"Get-WinEvent -FilterHashtable @{LogName='System'; Id=41,6008,1074; StartTime=(Get-Date).AddDays(-7)} |\n  Select-Object TimeCreated, Id, ProviderName, Message | Format-List","explanation":"41 et 6008 signalent un arrêt brutal ; 1074 un arrêt demandé (par exemple Windows Update). Les dates permettent de faire le lien avec l’activité.","isRealCase":true}],"alternatives":[{"slug":"linux-journalctl","note":"Équivalent pour les journaux systemd sous Linux."}],"sources":[{"title":"Get-WinEvent","url":"https://learn.microsoft.com/fr-fr/powershell/module/microsoft.powershell.diagnostics/get-winevent","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-tasklist","name":"tasklist","platform":"windows","shell":"cmd","difficulty":"beginner","requiresAdmin":false,"summary":"Liste les processus en cours avec leur identifiant (PID), leur mémoire et, au besoin, les services qu’ils hébergent.","history":"Présente depuis Windows XP Professionnel.","internals":"tasklist énumère les processus via l’API Windows ; /svc relie chaque processus svchost.exe aux services qu’il héberge.","syntax":"tasklist [/svc] [/v] [/fi \"filtre\"]","why":"Identifier ce qui tourne, et surtout quel service se cache derrière un svchost.exe qui consomme trop.","whenToUse":"Pour une vue rapide en ligne de commande ou à distance (/s). Le Gestionnaire des tâches reste plus confortable en local.","context":"Aucun droit particulier pour ses propres processus ; administrateur pour voir les détails de tous.","riskLevel":"none","risks":[{"level":"none","text":"Lecture seule."}],"bestPractices":["tasklist /svc /fi \"imagename eq svchost.exe\" pour savoir quels services hébergent les svchost.","Noter le PID avant d’utiliser taskkill."],"commonErrors":[],"parameters":[{"flag":"/svc","description":"Services hébergés par chaque processus.","riskLevel":"none"},{"flag":"/v","description":"Détails : utilisateur, temps CPU, titre de fenêtre.","riskLevel":"none"},{"flag":"/fi \"filtre\"","description":"Filtre (ex. \"memusage gt 500000\" en Ko).","riskLevel":"none"}],"examples":[{"title":"Un svchost consomme 2 Go de mémoire","code":"tasklist /svc /fi \"pid eq 3120\"","explanation":"Montre les services de ce processus ; on peut ensuite redémarrer le seul service fautif plutôt que la machine.","isRealCase":true}],"alternatives":[{"slug":"windows-taskkill","note":"Pour arrêter le processus identifié."},{"slug":"linux-ps","note":"Équivalent sous Linux."}],"sources":[{"title":"tasklist (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/tasklist","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-taskkill","name":"taskkill","platform":"windows","shell":"cmd","difficulty":"intermediate","requiresAdmin":false,"summary":"Arrête un ou plusieurs processus par leur PID ou leur nom.","history":"Présente depuis Windows XP Professionnel.","internals":"Sans /f, taskkill envoie une demande de fermeture (comme cliquer sur la croix) que l’application peut traiter. Avec /f, il appelle TerminateProcess : arrêt immédiat, sans enregistrement.","syntax":"taskkill /pid PID [/t] [/f]   |   taskkill /im nom.exe [/f]","why":"Fermer une application figée sans redémarrer le poste.","whenToUse":"Quand une application ne répond plus. Pour un service Windows, préférer l’arrêt du service (Stop-Service ou services.msc), qui prévient ses dépendances.","context":"On peut arrêter ses propres processus ; les processus système et ceux des autres utilisateurs demandent les droits d’administrateur.","riskLevel":"high","risks":[{"level":"medium","text":"Le travail non enregistré dans l’application est perdu."},{"level":"high","text":"/f sur un processus système (csrss.exe, wininit.exe, lsass.exe) provoque un écran bleu ou un redémarrage immédiat. /im arrête toutes les instances du même nom, y compris celles d’autres utilisateurs en bureau à distance."}],"bestPractices":["Cibler un PID plutôt qu’un nom.","Essayer d’abord sans /f.","Vérifier le PID avec tasklist juste avant."],"commonErrors":[{"error":"Accès refusé","cause":"Processus d’un autre utilisateur, ou processus protégé.","fix":"Relancer en administrateur si c’est justifié ; un processus protégé ne doit pas être arrêté."}],"parameters":[{"flag":"/pid PID","description":"Processus à arrêter.","riskLevel":"medium"},{"flag":"/im nom","description":"Toutes les instances portant ce nom.","riskLevel":"high"},{"flag":"/t","description":"Arrête aussi les processus enfants.","riskLevel":"medium"},{"flag":"/f","description":"Force l’arrêt immédiat.","riskLevel":"high"}],"examples":[{"title":"Fermer un Excel figé","code":"tasklist /fi \"imagename eq EXCEL.EXE\"\ntaskkill /pid 7744","explanation":"On cible le PID de l’instance figée ; si elle ne se ferme pas au bout de quelques secondes, on ajoute /f en sachant que les modifications non enregistrées sont perdues.","isRealCase":false}],"alternatives":[{"slug":"windows-tasklist","note":"Pour identifier le bon processus avant d’agir."},{"slug":"linux-kill","note":"Équivalent sous Linux."}],"sources":[{"title":"taskkill (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/taskkill","publisher":"Microsoft"}]}$json$::jsonb);

SELECT pg_temp.seed_command($json${"slug":"windows-bcdedit","name":"bcdedit","platform":"windows","shell":"cmd","difficulty":"advanced","requiresAdmin":true,"summary":"Affiche et modifie la configuration de démarrage de Windows (magasin BCD).","history":"Introduite avec Windows Vista, quand le fichier boot.ini a été remplacé par le magasin BCD.","internals":"Le magasin BCD est une base au format registre, stockée sur la partition système EFI (\\EFI\\Microsoft\\Boot\\BCD). Le gestionnaire de démarrage le lit pour savoir quel système charger et avec quelles options.","syntax":"bcdedit [/enum] [/export fichier] [/import fichier] [/set {id} option valeur]","why":"Comprendre et corriger un démarrage : entrée manquante, mode sans échec bloqué, options de débogage, double démarrage.","whenToUse":"En lecture (/enum) pour comprendre un démarrage. En écriture, seulement après avoir exporté le magasin et quand la réparation automatique de WinRE a échoué.","context":"Invite de commandes en administrateur, ou depuis l’environnement de récupération (WinRE).","riskLevel":"critical","risks":[{"level":"none","text":"/enum est en lecture seule."},{"level":"high","text":"Une option erronée (par exemple /set safeboot) peut enfermer le poste dans un mode de démarrage inattendu."},{"level":"critical","text":"Supprimer ou corrompre l’entrée {bootmgr} ou {current} rend Windows indémarrable ; seule une restauration du magasin ou une réparation depuis un support d’installation le relance."}],"bestPractices":["Toujours commencer par bcdedit /export C:\\bcd-sauvegarde.","Lire avec /enum all avant toute modification.","Essayer d’abord la réparation automatique du démarrage dans WinRE."],"commonErrors":[{"error":"Le magasin de données de configuration de démarrage n’a pas pu être ouvert. Accès refusé.","cause":"Invite de commandes non lancée en administrateur.","fix":"Relancer l’invite avec « Exécuter en tant qu’administrateur »."},{"error":"Le poste redémarre toujours en mode sans échec","cause":"Option safeboot posée et jamais retirée.","fix":"bcdedit /deletevalue {current} safeboot, puis redémarrer."}],"parameters":[{"flag":"/enum [all]","description":"Liste les entrées de démarrage.","riskLevel":"none"},{"flag":"/export fichier","description":"Sauvegarde le magasin.","riskLevel":"none"},{"flag":"/import fichier","description":"Remplace le magasin par une sauvegarde.","riskLevel":"high"},{"flag":"/set {id} option valeur","description":"Modifie une option de démarrage.","riskLevel":"high"},{"flag":"/delete {id}","description":"Supprime une entrée de démarrage.","riskLevel":"critical"}],"examples":[{"title":"Sortir d’un mode sans échec bloqué","code":"bcdedit /export C:\\bcd-sauvegarde\nbcdedit /enum {current}\nbcdedit /deletevalue {current} safeboot","explanation":"On sauvegarde, on vérifie que l’option safeboot est bien présente, puis on la retire. Les autres options ne sont pas touchées.","isRealCase":true}],"alternatives":[{"slug":"windows-sfc","note":"Quand Windows démarre mais que ses fichiers sont endommagés."}],"sources":[{"title":"bcdedit (Microsoft Learn)","url":"https://learn.microsoft.com/fr-fr/windows-server/administration/windows-commands/bcdedit","publisher":"Microsoft"}]}$json$::jsonb);

-- Alternatives en second temps : une fiche peut renvoyer vers une fiche créée plus bas.
INSERT INTO kb.command_alternatives (command_id, alternative_id, note)
SELECT c.id, a.id, x->>'note'
  FROM seeded_commands s
  CROSS JOIN jsonb_array_elements(s.alternatives) AS x
  JOIN kb.commands c ON c.slug = s.slug
  JOIN kb.commands a ON a.slug = x->>'slug' AND a.status = 'published'
ON CONFLICT DO NOTHING;

-- ----------------------------------------------------------------- Cours ----
CREATE FUNCTION pg_temp.seed_course(c jsonb) RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  course_id uuid;
  module_id uuid;
  lesson_id uuid;
  m jsonb;
  mi int;
  l jsonb;
  li int;
BEGIN
  IF EXISTS (SELECT 1 FROM learning.courses WHERE slug = c->>'slug') THEN RETURN; END IF;
  INSERT INTO learning.courses (slug, title, summary, platform, difficulty, is_premium, status)
  VALUES (c->>'slug', c->>'title', c->>'summary', (c->>'platform')::platform.os_platform,
          (c->>'difficulty')::platform.difficulty, (c->>'isPremium')::boolean, 'published')
  RETURNING id INTO course_id;
  FOR m, mi IN SELECT * FROM jsonb_array_elements(c->'modules') WITH ORDINALITY LOOP
    INSERT INTO learning.modules (course_id, title, position) VALUES (course_id, m->>'title', mi - 1)
    RETURNING id INTO module_id;
    FOR l, li IN SELECT * FROM jsonb_array_elements(m->'lessons') WITH ORDINALITY LOOP
      INSERT INTO learning.lessons (module_id, slug, title, type, content_md, objectives, est_minutes, position)
      VALUES (module_id, l->>'slug', l->>'title', l->>'type', l->>'contentMd',
              ARRAY(SELECT jsonb_array_elements_text(l->'objectives')), (l->>'estMinutes')::int, li - 1)
      RETURNING id INTO lesson_id;
      INSERT INTO learning.lesson_skills (lesson_id, skill_id)
      SELECT lesson_id, id FROM skills.skills WHERE code IN (SELECT jsonb_array_elements_text(l->'skills'));
    END LOOP;
  END LOOP;
END
$fn$;

SELECT pg_temp.seed_course($json${"slug":"linux-ligne-de-commande","title":"Linux : la ligne de commande sans danger","platform":"linux","difficulty":"beginner","isPremium":false,"summary":"Se déplacer, lire les droits, comprendre les processus et agir sans casser : les réflexes qui précèdent toute administration.","modules":[{"title":"Se repérer","lessons":[{"slug":"arborescence","title":"L’arborescence Linux : où est quoi","type":"reading","estMinutes":15,"skills":["linux.shell"],"objectives":["Situer /etc, /var, /home, /usr et /tmp","Savoir où chercher une configuration ou un journal"],"contentMd":"## Pourquoi c'est important\n\nSous Linux, **tout est un fichier** et chaque type de fichier a sa place. Savoir où regarder fait gagner un temps considérable : la configuration d'un service n'est jamais dans un dossier au hasard.\n\n## Comment c'est organisé\n\n| Dossier | Contient | Exemple |\n|---|---|---|\n| `/etc` | la **configuration**, en texte | `/etc/ssh/sshd_config` |\n| `/var` | ce qui **varie** : journaux, bases, files d'attente | `/var/log`, `/var/lib/postgresql` |\n| `/home` | les dossiers des utilisateurs | `/home/alice` |\n| `/usr` | les programmes installés par le système | `/usr/bin/ls` |\n| `/tmp` | les fichiers temporaires, souvent vidés au redémarrage | — |\n| `/proc`, `/sys` | une **vue du noyau**, pas de vrais fichiers | `/proc/meminfo` |\n\n## Quand s'en servir\n\n- Un service se comporte mal : sa configuration est dans `/etc/<service>`, ses données dans `/var/lib/<service>`.\n- Un disque se remplit : regardez d'abord `/var/log` et `/var/lib`.\n\n## Risques\n\nNe modifiez pas les fichiers de `/usr` à la main : le gestionnaire de paquets les écrasera à la prochaine mise à jour. Vos réglages vont dans `/etc`.\n\n## Alternatives\n\n`man hier` décrit l'arborescence complète de votre distribution."},{"slug":"lire-les-droits","title":"Lire et corriger les droits","type":"interactive","estMinutes":20,"skills":["linux.permissions"],"objectives":["Lire une ligne de ls -l","Choisir entre chmod et chown pour corriger un « Permission denied »"],"contentMd":"## Pourquoi\n\n« Permission denied » est l'erreur la plus fréquente sous Linux. Elle a toujours une explication précise, lisible en une ligne.\n\n## Comment lire `ls -l`\n\n```\n-rw-r----- 1 postgres postgres 4096 mars 3 10:12 pg_hba.conf\n│└┬┘└┬┘└┬┘   └──┬───┘ └──┬───┘\n│ │  │  │      │        └ groupe\n│ │  │  │      └ propriétaire\n│ │  │  └ autres : aucun droit\n│ │  └ groupe : lecture\n│ └ propriétaire : lecture, écriture\n└ type : - fichier, d répertoire, l lien\n```\n\nPour un **répertoire**, `x` signifie « traverser » : sans lui, on ne peut atteindre aucun fichier à l'intérieur, même lisible.\n\n## Méthode de diagnostic\n\n1. Qui exécute ? `id` (ou `ps -o user= -p PID` pour un service).\n2. Que demande-t-il ? lire, écrire, exécuter.\n3. `ls -ld` sur **chaque dossier du chemin** puis sur le fichier.\n4. Corriger le plus petit élément fautif : le **propriétaire** avec `chown`, ou les **droits** avec `chmod`.\n\n## Risques\n\n`chmod 777` « répare » tout en ouvrant tout : n'importe quel service compromis peut alors modifier le fichier. `chown -R` sur un mauvais chemin peut casser le système.\n\n## Alternatives\n\nPour donner l'accès à une personne précise sans changer le groupe, les **ACL** (`setfacl`) sont plus fines."}]},{"title":"Processus et sauvegardes","lessons":[{"slug":"processus-et-signaux","title":"Processus et signaux : arrêter proprement","type":"reading","estMinutes":20,"skills":["linux.processes"],"objectives":["Identifier le processus qui consomme une ressource","Expliquer la différence entre SIGTERM et SIGKILL"],"contentMd":"## Pourquoi\n\nUne machine lente ou un programme bloqué se traitent en identifiant **le** processus en cause, pas en redémarrant tout.\n\n## Comment\n\n1. **Identifier** : `ps aux --sort=-%cpu | head` (ou `--sort=-%mem`).\n2. **Comprendre** : à qui appartient-il ? est-ce un service (`systemctl status <pid>` le dit) ?\n3. **Agir** proprement :\n   - service → `systemctl restart nom` ;\n   - autre processus → `kill PID` (SIGTERM), attendre, vérifier.\n\n## SIGTERM ou SIGKILL ?\n\n| Signal | Qui agit | Conséquence |\n|---|---|---|\n| SIGTERM (15) | le programme | il ferme ses fichiers, libère ses verrous, puis s'arrête |\n| SIGKILL (9) | le noyau | arrêt immédiat ; rien n'est nettoyé |\n\n## Risques\n\n- Arrêter un processus interrompt ce qu'il faisait : sessions d'utilisateurs, traitements en cours.\n- **-9** empêche tout nettoyage : verrous et écritures en cours peuvent rester incohérents. N'y recourir que si SIGTERM est resté sans effet, et jamais sur une base de données.\n- Un PID peut être réutilisé : vérifiez-le (`ps -p PID -o cmd`) juste avant d'agir.\n\n## États à connaître\n\n- **D** : bloqué dans le noyau (souvent un disque ou un partage réseau). Même -9 n'y peut rien : cherchez l'entrée-sortie en cause.\n- **Z** : zombie, déjà mort. C'est son parent qui doit le récupérer.\n\n## Alternatives\n\n`top` ou `htop` pour suivre l'évolution en direct."},{"slug":"sauvegarder-avant-modifier","title":"Sauvegarder avant de modifier","type":"lab","estMinutes":15,"skills":["linux.shell"],"objectives":["Archiver une configuration avec tar avant une modification","Revenir en arrière en une commande"],"contentMd":"## Pourquoi\n\nLa plupart des incidents d'administration viennent d'une modification. Une copie de 10 secondes permet un retour arrière immédiat.\n\n## Comment\n\n```bash\nsudo tar -czf ~/nginx-$(date +%F-%H%M).tar.gz /etc/nginx\ntar -tzf ~/nginx-*.tar.gz | head     # vérifier le contenu\n```\n\nModifier, puis **valider avant de recharger** : `sudo nginx -t` (la plupart des services ont un équivalent).\n\nRetour arrière :\n\n```bash\nsudo tar -xzf ~/nginx-2026-11-23-1012.tar.gz -C /\nsudo systemctl reload nginx\n```\n\n## Quand\n\nAvant toute modification de `/etc`, avant une mise à jour majeure, avant un script qui écrit beaucoup de fichiers.\n\n## Risques\n\nL'extraction **écrase** sans demander. Listez toujours le contenu d'une archive avant de l'extraire, surtout avec `-C /`.\n\n## Alternatives\n\n`etckeeper` versionne `/etc` avec Git automatiquement : chaque modification devient un commit consultable."}]}]}$json$::jsonb);

SELECT pg_temp.seed_course($json${"slug":"linux-reseau","title":"Linux : diagnostiquer le réseau","platform":"linux","difficulty":"intermediate","isPremium":false,"summary":"Une méthode couche par couche pour savoir si le problème vient de l’interface, de la route, du DNS ou du service.","modules":[{"title":"Méthode couche par couche","lessons":[{"slug":"interface-et-route","title":"Interface, adresse et route","type":"interactive","estMinutes":20,"skills":["linux.network"],"objectives":["Vérifier qu’une interface est active et adressée","Trouver la route par défaut et le chemin d’un paquet"],"contentMd":"## Pourquoi\n\nAvant d'accuser le pare-feu ou le DNS, il faut vérifier les fondations : sans interface active ni route, rien ne sort.\n\n## Comment, dans l'ordre\n\n```bash\nip -br a                 # 1. interface UP avec une adresse ?\nip route                 # 2. une ligne « default via … » ?\nip route get 1.1.1.1     # 3. chemin réellement choisi\nping -c3 <passerelle>    # 4. la passerelle répond-elle ?\n```\n\n| Constat | Cause probable |\n|---|---|\n| Interface DOWN | câble, Wi-Fi, ou interface désactivée |\n| Pas d'adresse | DHCP en échec, configuration absente |\n| Pas de route par défaut | passerelle non configurée |\n| Passerelle muette | réseau local, VLAN, équipement |\n\n## Quand\n\nAu tout début de chaque incident réseau, même « évident ».\n\n## Risques\n\nLire ne coûte rien. Modifier (`ip link set … down`, `ip route del`) sur l'interface de votre session SSH **coupe votre accès**. Et ces modifications disparaissent au redémarrage.\n\n## Alternatives\n\n`nmcli` (NetworkManager) ou `networkctl` (systemd-networkd) montrent la même chose et gèrent la configuration **durable**."},{"slug":"dns-ou-reseau","title":"DNS ou réseau ? Trancher en deux commandes","type":"reading","estMinutes":15,"skills":["network.dns"],"objectives":["Distinguer une panne DNS d’une panne réseau","Lire NXDOMAIN et SERVFAIL"],"contentMd":"## Pourquoi\n\n« Internet ne marche pas » veut souvent dire « les noms ne se résolvent pas ». Les causes et les correctifs sont très différents.\n\n## Comment\n\n```bash\nping -c3 1.1.1.1          # le réseau fonctionne-t-il ?\ndig +short exemple.fr     # le DNS répond-il ?\ndig @1.1.1.1 exemple.fr   # un autre résolveur répond-il ?\n```\n\n| IP | DNS local | DNS public | Conclusion |\n|---|---|---|---|\n| ✗ | ✗ | ✗ | réseau : revoir interface et route |\n| ✓ | ✗ | ✓ | **résolveur local** en panne ou mal configuré |\n| ✓ | ✗ | ✗ | le nom n'existe pas, ou le domaine est en panne |\n\n## Lire la réponse de dig\n\n- **NOERROR** sans réponse : le nom existe, pas pour ce type d'enregistrement.\n- **NXDOMAIN** : le nom n'existe pas (faute de frappe, enregistrement manquant).\n- **SERVFAIL** : le serveur n'a pas pu répondre (DNSSEC, serveur autoritaire injoignable).\n\n## Où est configuré le résolveur ?\n\n`resolvectl status` sur les systèmes avec systemd-resolved, sinon `/etc/resolv.conf`.\n\n## Risques\n\nAucun pour le diagnostic. Remplacer le résolveur d'un serveur d'entreprise par un DNS public casse la résolution des noms **internes**."},{"slug":"service-joignable","title":"Le service écoute-t-il ?","type":"lab","estMinutes":20,"skills":["linux.network"],"objectives":["Vérifier le port et l’adresse d’écoute d’un service","Distinguer un service arrêté d’un pare-feu fermé"],"contentMd":"## Pourquoi\n\nLe réseau et le DNS fonctionnent, mais le site ne répond pas. Il reste trois suspects : le service, son adresse d'écoute, le pare-feu.\n\n## Comment\n\n```bash\nsystemctl status nginx              # 1. le service tourne-t-il ?\nsudo ss -tlnp 'sport = :443'        # 2. écoute-t-il, et sur quelle adresse ?\ncurl -sv https://localhost/ -k      # 3. répond-il en local ?\nsudo ufw status  # ou firewall-cmd --list-all   # 4. pare-feu\n```\n\n| Constat | Conclusion |\n|---|---|\n| Service arrêté | lire `journalctl -u nginx` |\n| Écoute sur 127.0.0.1 | il n'est joignable qu'en local : changer l'adresse d'écoute |\n| Répond en local, pas de l'extérieur | pare-feu ou groupe de sécurité du cloud |\n\n## Quand\n\nAprès avoir validé interface, route et DNS.\n\n## Risques\n\nOuvrir un port « pour voir » expose le service à Internet. Ouvrez seulement le port nécessaire, et seulement aux adresses qui en ont besoin.\n\n## Alternatives\n\n`nc -zv hôte port` teste un port TCP depuis un autre poste."}]}]}$json$::jsonb);

SELECT pg_temp.seed_course($json${"slug":"linux-stockage","title":"Linux : disque plein et stockage","platform":"linux","difficulty":"intermediate","isPremium":false,"summary":"Trouver ce qui remplit un disque, libérer de la place sans rien casser, et éviter que cela recommence.","modules":[{"title":"Disque plein","lessons":[{"slug":"disque-plein-methode","title":"Disque plein : la méthode df puis du","type":"interactive","estMinutes":20,"skills":["linux.storage"],"objectives":["Identifier la partition pleine","Descendre jusqu’au dossier responsable"],"contentMd":"## Pourquoi\n\nUn disque plein ne prévient pas : les bases passent en lecture seule, les journaux s'arrêtent, les services échouent avec des messages trompeurs.\n\n## Comment\n\n```bash\ndf -h                                     # 1. quelle partition ?\ndf -i                                     # 2. ou bien les inodes ?\nsudo du -xh --max-depth=1 /var | sort -h  # 3. quel dossier ?\n```\n\nRecommencez l'étape 3 sur le plus gros dossier jusqu'à trouver la cause. Les coupables habituels :\n\n- `/var/log` : journaux non tournés ;\n- `/var/lib/docker` : images et conteneurs arrêtés ;\n- `/var/cache` : paquets téléchargés ;\n- un fichier de vidage (`core`) ou une sauvegarde oubliée.\n\n## Le piège : df et du ne sont pas d'accord\n\nUn fichier **supprimé mais encore ouvert** occupe toujours la place. `sudo lsof +L1` montre le processus qui le garde ouvert ; redémarrez-le proprement.\n\n## Risques\n\nSupprimer « ce qui est gros » sans comprendre peut détruire une base de données. Ne touchez jamais aux fichiers de `/var/lib/postgresql` ou `/var/lib/mysql` à la main.\n\n## Alternatives\n\n`ncdu` offre une navigation interactive dans les tailles."},{"slug":"liberer-sans-casser","title":"Libérer de la place sans rien casser","type":"case_study","estMinutes":25,"skills":["linux.storage","linux.journald"],"objectives":["Nettoyer journaux, caches et images avec les outils prévus","Mettre en place une limite pour éviter la récidive"],"contentMd":"## Pourquoi\n\nChaque type de données a son outil de nettoyage : il sait ce qui est sûr à supprimer, contrairement à `rm`.\n\n## Comment\n\n| Coupable | Nettoyage sûr | Prévention |\n|---|---|---|\n| journald | `sudo journalctl --vacuum-size=500M` | `SystemMaxUse=500M` dans `/etc/systemd/journald.conf` |\n| journaux applicatifs | `logrotate` (vérifier `/etc/logrotate.d`) | rotation et compression quotidiennes |\n| cache apt | `sudo apt clean` | — |\n| Docker | `docker system df` puis `docker image prune` | limiter la taille des journaux des conteneurs |\n\n## Cas réel\n\nUn serveur web s'arrête un dimanche. `df -h` : `/` à 100 %. `du` mène à `/var/log/nginx/access.log` : 38 Go, la rotation était désactivée. Correctif immédiat : `sudo truncate -s 0` sur le journal (et non `rm`, qui laisse le fichier ouvert par nginx). Correctif durable : réactiver logrotate.\n\n## Risques\n\n- `docker system prune -a --volumes` supprime aussi les **volumes** non utilisés, donc des données.\n- `rm` sur un journal ouvert ne libère rien tant que le service tourne.\n\n## Alternatives\n\nUne alerte de supervision à 80 % d'occupation évite d'avoir à intervenir dans l'urgence."}]}]}$json$::jsonb);

SELECT pg_temp.seed_course($json${"slug":"windows-reseau","title":"Windows : dépanner le réseau d’un poste","platform":"windows","difficulty":"beginner","isPremium":false,"summary":"Configuration IP, connectivité, DNS : une méthode par couches pour résoudre la plupart des « pas d’Internet ».","modules":[{"title":"Méthode par couches","lessons":[{"slug":"lire-ipconfig","title":"Lire ipconfig /all","type":"interactive","estMinutes":15,"skills":["windows.network"],"objectives":["Repérer une adresse APIPA","Vérifier passerelle et serveurs DNS"],"contentMd":"## Pourquoi\n\nLa configuration IP dit déjà beaucoup : un poste sans adresse valide ou sans passerelle ne pourra jamais sortir, quel que soit le reste.\n\n## Comment\n\n`ipconfig /all`, puis lire pour la carte active :\n\n| Ligne | Ce qu'on vérifie |\n|---|---|\n| Adresse IPv4 | **169.254.x.x** = aucun serveur DHCP n'a répondu |\n| Passerelle par défaut | vide = pas de sortie possible |\n| Serveurs DNS | ceux de l'entreprise sur un poste du domaine |\n| DHCP activé / Bail obtenu | savoir d'où vient la configuration |\n\n## Quand\n\nEn premier, pour tout problème réseau.\n\n## Risques\n\nLire ne coûte rien. `ipconfig /release` coupe la carte : jamais en bureau à distance.\n\n## Alternatives\n\nDans PowerShell, `Get-NetIPConfiguration` donne la même information, plus facile à utiliser dans un script."},{"slug":"ping-par-couches","title":"Tester par couches avec ping et tracert","type":"interactive","estMinutes":20,"skills":["windows.network"],"objectives":["Localiser une coupure entre le poste et Internet","Interpréter un délai dépassé sans conclure trop vite"],"contentMd":"## Pourquoi\n\nChaque test qui réussit élimine une famille de causes. En trois commandes, on sait si le problème est local, chez le fournisseur ou côté DNS.\n\n## Comment\n\n```\nping 192.168.1.1      (passerelle)\nping 1.1.1.1          (Internet par adresse)\nping www.exemple.fr   (Internet par nom)\n```\n\n| Passerelle | 1.1.1.1 | Nom | Conclusion |\n|---|---|---|---|\n| ✗ | ✗ | ✗ | réseau local : câble, Wi-Fi, carte |\n| ✓ | ✗ | ✗ | box, fournisseur ou pare-feu de sortie |\n| ✓ | ✓ | ✗ | **DNS** |\n| ✓ | ✓ | ✓ | le réseau va bien : regarder l'application ou le proxy |\n\nSi 1.1.1.1 échoue, `tracert -d 1.1.1.1` montre le dernier équipement qui répond.\n\n## Attention\n\nUn « délai d'attente dépassé » ne prouve pas que la machine est éteinte : beaucoup de pare-feu, dont celui de Windows, bloquent ping.\n\n## Risques\n\nAucun."},{"slug":"resoudre-dns-windows","title":"Résoudre un problème DNS","type":"case_study","estMinutes":20,"skills":["network.dns","windows.network"],"objectives":["Comparer deux serveurs DNS avec nslookup","Savoir quand vider le cache DNS"],"contentMd":"## Pourquoi\n\nQuand les adresses répondent mais pas les noms, il est inutile de redémarrer la box : c'est la résolution de noms qu'il faut examiner.\n\n## Comment\n\n```\nnslookup intranet.exemple.local\nnslookup intranet.exemple.local 1.1.1.1\nipconfig /flushdns\n```\n\n- Le DNS interne répond, le public non : normal pour un nom **interne**.\n- Aucun ne répond : enregistrement manquant ou mal orthographié.\n- nslookup répond mais pas le navigateur : cache local (`/flushdns`), fichier `hosts`, ou proxy.\n\n## Cas réel\n\nAprès la migration d'un serveur, une partie des postes ouvre encore l'ancien. `nslookup` donne bien la nouvelle adresse : les postes fautifs gardent l'ancienne en cache, jusqu'à la fin de sa durée de validité (TTL). `ipconfig /flushdns` corrige immédiatement. Pour la prochaine fois : baisser le TTL quelques jours avant une migration.\n\n## Risques\n\nForcer un DNS public sur un poste du domaine casse l'ouverture de session et l'accès aux partages internes."}]}]}$json$::jsonb);

SELECT pg_temp.seed_course($json${"slug":"windows-disques","title":"Windows : disques, fichiers système et démarrage","platform":"windows","difficulty":"intermediate","isPremium":false,"summary":"Vérifier un disque, réparer les fichiers de Windows dans le bon ordre et remettre en route un démarrage bloqué.","modules":[{"title":"Réparer dans le bon ordre","lessons":[{"slug":"chkdsk-sans-risque","title":"Vérifier un disque sans le mettre en danger","type":"reading","estMinutes":15,"skills":["windows.disk"],"objectives":["Choisir entre /scan, /spotfix, /f et /r","Savoir quand sauvegarder avant de réparer"],"contentMd":"## Pourquoi\n\nUne coupure de courant ou un disque fatigué peuvent laisser le système de fichiers incohérent. Mais une réparation lancée trop vite sur un disque mourant peut faire perdre les données qu'on voulait sauver.\n\n## Comment\n\n| Étape | Commande | Effet |\n|---|---|---|\n| 1 | `chkdsk C: /scan` | analyse, ne modifie rien |\n| 2 | `chkdsk C: /spotfix` | corrige seulement ce qui a été trouvé |\n| 3 | `chkdsk C: /f` | réparation complète (au redémarrage pour C:) |\n| 4 | `chkdsk C: /r` | lit tout le disque : long, et éprouvant pour un disque défaillant |\n\n## Quand sauvegarder d'abord\n\n- bruits anormaux, lenteurs extrêmes ;\n- événements **disk 7** ou **153** dans le journal Système ;\n- attributs SMART en alerte (`Get-PhysicalDisk | Get-StorageReliabilityCounter`).\n\nDans ces cas, **copiez les données avant toute réparation**.\n\n## Risques\n\n`/f` peut déplacer des fichiers trop endommagés dans `found.000`. `/r` peut achever un disque mécanique.\n\n## Alternatives\n\nSur un SSD, `/r` n'apporte rien : le contrôleur gère lui-même les cellules défaillantes."},{"slug":"chaine-de-reparation","title":"chkdsk, DISM puis SFC : pourquoi cet ordre","type":"reading","estMinutes":15,"skills":["windows.repair","windows.disk"],"objectives":["Expliquer ce que répare chaque outil","Enchaîner les réparations dans l’ordre qui fonctionne"],"contentMd":"## Pourquoi\n\nLes trois outils réparent des **couches différentes**. Les lancer dans le désordre donne des échecs incompréhensibles.\n\n## Les couches\n\n1. **Système de fichiers** (chkdsk) : la structure qui permet de lire n'importe quel fichier.\n2. **Magasin de composants** (DISM) : les copies de référence des fichiers de Windows, dans `C:\\Windows\\WinSxS`.\n3. **Fichiers système** (SFC) : les fichiers utilisés par Windows, restaurés **depuis** le magasin.\n\n## Donc\n\n```\nchkdsk C: /scan\nDISM /Online /Cleanup-Image /RestoreHealth\nsfc /scannow\n```\n\nSi le magasin est abîmé, SFC ne peut pas réparer : il n'a plus de bonne copie à recopier. D'où DISM **avant** SFC.\n\n## Quand\n\nPlantages d'applications Windows, écrans bleus récurrents sans pilote en cause, mises à jour qui échouent toujours.\n\n## Risques\n\nFaibles : ces outils ne remplacent que des fichiers de Windows par leur version d'origine. DISM a besoin de Windows Update ou d'une source (`/Source`).\n\n## Alternatives\n\nSi tout échoue, la **réinstallation sur place** (mise à niveau avec le même ISO) conserve fichiers et applications."},{"slug":"demarrage-bloque","title":"Remettre en route un démarrage bloqué","type":"case_study","estMinutes":25,"skills":["windows.boot"],"objectives":["Utiliser l’environnement de récupération (WinRE)","Sauvegarder et lire le magasin BCD avant de le modifier"],"contentMd":"## Pourquoi\n\nUn poste qui ne démarre plus n'est pas forcément à réinstaller : la plupart des démarrages bloqués se réparent depuis l'environnement de récupération.\n\n## Comment\n\n1. Accéder à **WinRE** : trois démarrages interrompus de suite, ou maintenir Maj en cliquant sur « Redémarrer ».\n2. *Dépannage → Options avancées → Outil de redémarrage système* : la réparation automatique, **à essayer en premier**.\n3. Si elle échoue, *Invite de commandes* :\n\n```\nbcdedit /export C:\\bcd-sauvegarde\nbcdedit /enum all\n```\n\n## Cas réel\n\nUn poste redémarre en boucle en mode sans échec après une intervention. `bcdedit /enum {current}` montre `safeboot Minimal`. Correctif : `bcdedit /deletevalue {current} safeboot`. Le poste redémarre normalement ; la sauvegarde du magasin n'a pas servi, mais elle aurait permis de revenir en arrière.\n\n## Risques\n\n`bcdedit /delete` sur la mauvaise entrée rend Windows **indémarrable**. Toujours exporter le magasin avant, et ne toucher qu'à l'option identifiée.\n\n## Alternatives\n\n`bootrec /rebuildbcd` reconstruit le magasin automatiquement ; sur un poste UEFI, `bcdboot C:\\Windows` recrée les fichiers de démarrage de la partition EFI."}]}]}$json$::jsonb);

-- -------------------------------------------------------------- Parcours ----
-- L'ordre d'un parcours n'est réécrit que s'il lui manque un des cours prévus (premier chargement).
-- Un événement learning.path.published.v1 fait alors recalculer la progression des inscrits.
CREATE FUNCTION pg_temp.seed_path(p_slug text, wanted text[]) RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  pid uuid;
BEGIN
  SELECT id INTO pid FROM learning.learning_paths WHERE slug = p_slug;
  IF pid IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM unnest(wanted) AS w(slug)
      JOIN learning.courses c ON c.slug = w.slug
     WHERE NOT EXISTS (SELECT 1 FROM learning.path_courses pc WHERE pc.path_id = pid AND pc.course_id = c.id)
  ) THEN RETURN; END IF;
  DELETE FROM learning.path_courses WHERE path_id = pid;
  INSERT INTO learning.path_courses (path_id, course_id, position)
  SELECT pid, c.id, row_number() OVER (ORDER BY w.ord)
    FROM unnest(wanted) WITH ORDINALITY AS w(slug, ord)
    JOIN learning.courses c ON c.slug = w.slug;
  INSERT INTO platform.outbox_events (aggregate, aggregate_id, type, payload)
  VALUES ('learning.path', pid, 'learning.path.published.v1',
          jsonb_build_object('kind', 'path', 'targetId', pid, 'key', p_slug, 'source', 'seed'));
END
$fn$;

SELECT pg_temp.seed_path('administrateur-linux', ARRAY['linux-ligne-de-commande', 'linux-systemd', 'linux-reseau', 'linux-stockage']);
SELECT pg_temp.seed_path('technicien-informatique', ARRAY['windows-fondamentaux', 'windows-reseau', 'windows-disques']);

COMMIT;
